import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { describe, expect, it } from "vitest";

const require = createRequire(import.meta.url);
const plugin = require("../expo-plugin/plugin.js") as {
  addPod(podfile: string, harnessPath: string): string;
  addHarnessStart(appDelegate: string, port: number): string;
};

// Real files generated by `expo prebuild` (Expo 57 / RN 0.86).
const fixture = (name: string) => readFileSync(new URL(`./fixtures/${name}`, import.meta.url), "utf8");

describe("expo plugin: Podfile", () => {
  it("adds the Debug-only pod after use_expo_modules!", () => {
    const out = plugin.addPod(fixture("Podfile"), "../../app-mcp/swift-harness");
    expect(out).toContain(
      "  use_expo_modules!\n  pod 'AppMCPHarness', :path => '../../app-mcp/swift-harness', :configurations => ['Debug']\n",
    );
  });

  it("is idempotent", () => {
    const once = plugin.addPod(fixture("Podfile"), "../h");
    expect(plugin.addPod(once, "../h")).toBe(once);
  });
});

describe("expo plugin: AppDelegate.swift", () => {
  const out = plugin.addHarnessStart(fixture("AppDelegate.swift"), 8787);

  it("imports the harness behind #if DEBUG after the last import", () => {
    expect(out).toContain("import ReactAppDependencyProvider\n#if DEBUG\nimport AppMCPHarness\n#endif\n");
  });

  it("starts it first thing in didFinishLaunchingWithOptions, DEBUG only", () => {
    expect(out).toMatch(
      /didFinishLaunchingWithOptions[^{]*\{\n#if DEBUG\n {4}AppMCP\.start\(port: 8787\)\n#endif\n {4}let delegate = ReactNativeDelegate\(\)/,
    );
  });

  it("is idempotent", () => {
    expect(plugin.addHarnessStart(out, 8787)).toBe(out);
  });
});
